package com.sgn.modelos;

import com.sgn.excepciones.*;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Clase que representa un alumno del instituto.
 * 
 * <p>Un Alumno tiene nombre, email, NIE y un historial
 * academico con todas sus notas.</p>
 * 
 * @author Programacion 1. DAM/DAW
 * @version 1.0
 */
public class Alumno extends Persona implements Serializable, Comparable<Alumno> {

    private static final long serialVersionUID = 1L;

    /** Nota minima para estar aprobado */
    public static final double NOTA_APROBADO = 5.0;

    /** Nota maxima posible */
    public static final double NOTA_MAXIMA = 10.0;

    private String nie;
    private final HistorialAcademico historial;

    /**
     * Crea un nuevo alumno.
     * 
     * @param nombre nombre completo del alumno
     * @param email direccion de correo electronico
     * @param nie numero de identificacion del estudiante
     * @throws NombreInvalidoException si el nombre no es valido
     * @throws EmailInvalidoException si el email no es valido
     */
    public Alumno(String nombre, String email, String nie)
            throws NombreInvalidoException, EmailInvalidoException {
        super(nombre, email);
        if (nombre == null || nombre.isBlank()) {
            throw new NombreInvalidoException(nombre);
        }
        if (email == null || !email.contains("@")) {
            throw new EmailInvalidoException(email);
        }
        this.nie = nie;
        this.historial = new HistorialAcademico();
    }

    @Override
    public String getRol() { return "Alumno"; }

    public String getNie() { return nie; }

    /**
     * Aniade una nota al historial del alumno.
     * 
     * @param nota la nota a aniadir (0.0 - 10.0)
     * @param curso el curso al que pertenece la nota
     * @param tipo tipo de evaluacion
     * @throws NotaInvalidaException si la nota no esta en el rango valido
     */
    public void addNota(double nota, Curso curso, TipoEvaluacion tipo)
            throws NotaInvalidaException {
        if (nota < 0 || nota > NOTA_MAXIMA) {
            throw new NotaInvalidaException(nota, nombre);
        }
        historial.addNota(new Nota(curso, nota, tipo));
    }

    public double getNotaMedia() {
        return historial.getMedia();
    }

    public int getNumNotas() {
        return historial.getNumNotas();
    }

    public List<Nota> getNotas() {
        return historial.getNotas();
    }

    public List<Nota> getNotasCurso(Curso curso) {
        return historial.getNotasCurso(curso);
    }

    public boolean estaAprobado() {
        return getNotaMedia() >= NOTA_APROBADO;
    }

    /**
     * Obtiene un resumen del alumno.
     * 
     * @return string con nombre, email y nota media
     */
    public String getResumen() {
        return String.format("%s (%s) - Media: %.2f - %s",
            nombre, email, getNotaMedia(),
            estaAprobado() ? "Aprobado" : "Suspensa");
    }

    @Override
    public int compareTo(Alumno otro) {
        return Double.compare(otro.getNotaMedia(), this.getNotaMedia());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Alumno alumno = (Alumno) o;
        return Objects.equals(nie, alumno.nie);
    }

    @Override
    public int hashCode() {
        return Objects.hash(nie);
    }

    @Override
    public String toString() {
        return String.format("%s [%s] - Media: %.2f",
            nombre, nie, getNotaMedia());
    }
}

package com.sgn.modelos;

