package com.sgn.modelos;

import java.io.Serializable;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

/**
 * Representa una calificacion de un alumno en un curso.
 */
public class Nota implements Serializable {

    private static final long serialVersionUID = 1L;

    private final Curso curso;
    private final double valor;
    private final TipoEvaluacion tipo;
    private final LocalDate fecha;

    public Nota(Curso curso, double valor, TipoEvaluacion tipo) {
        this.curso = curso;
        this.valor = valor;
        this.tipo = tipo;
        this.fecha = LocalDate.now();
    }

    public Nota(Curso curso, double valor, TipoEvaluacion tipo, LocalDate fecha) {
        this.curso = curso;
        this.valor = valor;
        this.tipo = tipo;
        this.fecha = fecha;
    }

    public Curso getCurso() { return curso; }
    public double getValor() { return valor; }
    public TipoEvaluacion getTipo() { return tipo; }
    public LocalDate getFecha() { return fecha; }

    public boolean estaAprobado() {
        return valor >= Alumno.NOTA_APROBADO;
    }

    @Override
    public String toString() {
        return String.format("%s: %.1f (%s) [%s]",
            curso.getNombre(), valor, tipo,
            fecha.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));
    }
}

package com.sgn.modelos;

import com.sgn.excepciones.*;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

/**
 * Representa un curso del instituto.
 */
public class Curso implements Serializable {

    private static final long serialVersionUID = 1L;

    private String nombre;
    private int horasTotales;
    private int capacidadMaxima;
    private final List<Alumno> alumnosMatriculados;

    public Curso(String nombre, int horasTotales, int capacidadMaxima) {
        this.nombre = nombre;
        this.horasTotales = horasTotales;
        this.capacidadMaxima = capacidadMaxima;
        this.alumnosMatriculados = new ArrayList<>();
    }

    /**
     * Matricula un alumno en el curso.
     * 
     * @param alumno el alumno a matricular
     * @throws CursoLlenoException si el curso esta lleno
     */
    public void matricular(Alumno alumno) throws CursoLlenoException {
        if (alumnosMatriculados.size() >= capacidadMaxima) {
            throw new CursoLlenoException(nombre, capacidadMaxima);
        }
        if (alumnosMatriculados.contains(alumno)) {
            return; // Ya esta matriculado
        }
        alumnosMatriculados.add(alumno);
    }

    /**
     * Desmatricula un alumno del curso.
     */
    public void desmatricular(Alumno alumno) {
        alumnosMatriculados.remove(alumno);
    }

    public String getNombre() { return nombre; }
    public int getHorasTotales() { return horasTotales; }
    public int getCapacidadMaxima() { return capacidadMaxima; }
    public int getNumAlumnos() { return alumnosMatriculados.size(); }
    public boolean estaLleno() { return alumnosMatriculados.size() >= capacidadMaxima; }
    public List<Alumno> getAlumnosMatriculados() {
        return new ArrayList<>(alumnosMatriculados);
    }

    public double getNotaMediaCurso() {
        if (alumnosMatriculados.isEmpty()) return 0;
        double suma = 0;
        for (Alumno a : alumnosMatriculados) {
            suma += a.getNotaMedia();
        }
        return suma / alumnosMatriculados.size();
    }

    @Override
    public String toString() {
        return String.format("%s (%d h) [%d/%d alumnos]",
            nombre, horasTotales, getNumAlumnos(), capacidadMaxima);
    }
}

package com.sgn.modelos;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Historial academico de un alumno: agrupa todas sus notas.
 */
public class HistorialAcademico implements Serializable {

    private static final long serialVersionUID = 1L;

    private final List<Nota> notas;

    public HistorialAcademico() {
        this.notas = new ArrayList<>();
    }

    public void addNota(Nota nota) {
        notas.add(nota);
    }

    public double getMedia() {
        if (notas.isEmpty()) return 0;
        return notas.stream()
            .mapToDouble(Nota::getValor)
            .average()
            .orElse(0);
    }

    public int getNumNotas() { return notas.size(); }

    public List<Nota> getNotas() {
        return new ArrayList<>(notas);
    }

    public List<Nota> getNotasCurso(Curso curso) {
        return notas.stream()
            .filter(n -> n.getCurso().equals(curso))
            .collect(Collectors.toList());
    }

    public int getNumAprobadas() {
        return (int) notas.stream()
            .filter(Nota::estaAprobado)
            .count();
    }

    public int getNumSuspensas() {
        return notas.size() - getNumAprobadas();
    }
}

package com.sgn.excepciones;

/**
 * Excepcion base del sistema SGN.
 */
public class SGNException extends Exception {
    public SGNException(String mensaje) { super(mensaje); }
    public SGNException(String mensaje, Throwable causa) { super(mensaje, causa); }
}

// === NotaInvalidaException ===
package com.sgn.excepciones;

public class NotaInvalidaException extends SGNException {
    private final double notaInvalida;
    private final String alumno;

    public NotaInvalidaException(double nota, String alumno) {
        super(String.format("Nota invalida: %.1f para '%s'. Debe estar entre 0.0 y 10.0.",
            nota, alumno));
        this.notaInvalida = nota;
        this.alumno = alumno;
    }

    public double getNotaInvalida() { return notaInvalida; }
    public String getAlumno() { return alumno; }
}

// === EmailInvalidoException ===
package com.sgn.excepciones;

public class EmailInvalidoException extends SGNException {
    private final String email;
    public EmailInvalidoException(String email) {
        super("Email invalido: " + email);
        this.email = email;
    }
    public String getEmail() { return email; }
}

// === CursoLlenoException ===
package com.sgn.excepciones;

public class CursoLlenoException extends SGNException {
    private final String curso;
    private final int capacidad;
    public CursoLlenoException(String curso, int capacidad) {
        super("Curso " + curso + " lleno (max: " + capacidad + " alumnos)");
        this.curso = curso;
        this.capacidad = capacidad;
    }
}

// === AlumnoNoEncontradoException ===
package com.sgn.excepciones;

public class AlumnoNoEncontradoException extends SGNException {
    private final String nombre;
    public AlumnoNoEncontradoException(String nombre) {
