package com.sgn.persistencia;

import com.sgn.modelos.GestorAcademico;
import java.io.*;

/**
 * Gestor de persistencia con serialización de objetos.
 */
public class GestorPersistencia {

    private static final String RUTA_BACKUP = "datos.dat.bak";

    /**
     * Guarda el GestorAcademico en un fichero.
     * Crea un backup del fichero anterior si existe.
     */
    public static void guardar(GestorAcademico gestor, String ruta)
            throws IOException {
        File fichero = new File(ruta);

        // Crear backup si existe
        if (fichero.exists()) {
            File backup = new File(RUTA_BACKUP);
            if (backup.exists()) backup.delete();
            fichero.renameTo(backup);
        }

        try (ObjectOutputStream oos = new ObjectOutputStream(
                new FileOutputStream(ruta))) {
            oos.writeObject(gestor);
        }
    }

    /**
     * Carga un GestorAcademico desde un fichero.
     * Devuelve un GestorAcademico vacio si no existe el fichero.
     */
    public static GestorAcademico cargar(String ruta) {
        try (ObjectInputStream ois = new ObjectInputStream(
                new FileInputStream(ruta))) {
            return (GestorAcademico) ois.readObject();
        } catch (FileNotFoundException e) {
            System.out.println("No se encontro fichero de datos. Iniciando vacio.");
            return new GestorAcademico();
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error cargando datos: " + e.getMessage());
            return new GestorAcademico();
        }
    }

    /**
     * Comprueba si existe un fichero de datos.
     */
    public static boolean existeFichero(String ruta) {
        return new File(ruta).exists();
    }
}

