import java.util.List;

/**
 * Exportador de alumnos a formato CSV.
 */
public class ExportadorCSV {

    /**
     * Exporta una lista de alumnos a un fichero CSV.
     * 
     * @param alumnos lista de alumnos a exportar
     * @param ruta ruta del fichero CSV de salida
     * @throws IOException si hay error de escritura
     */
    public static void exportar(List<Alumno> alumnos, String ruta)
            throws IOException {
        try (PrintWriter pw = new PrintWriter(new BufferedWriter(
                new FileWriter(ruta)))) {

            // Cabecera CSV
            pw.println("Nombre,Email,NIE,Notas,Media,Estado");

            // Datos
            for (Alumno a : alumnos) {
                pw.printf("%s,%s,%s,%d,%.2f,%s%n",
                    a.getNombre(),
                    a.getEmail(),
                    a.getNie(),
                    a.getNumNotas(),
                    a.getNotaMedia(),
                    a.estaAprobado() ? "Aprobado" : "Suspensa");
            }
        }
    }
}

package com.sgn.persistencia;

import com.sgn.modelos.*;
