import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * Generador de informes de texto formateados.
 */
public class GeneradorInformes {

    /**
     * Genera un informe completo del sistema.
     */
    public static void generarInforme(GestorAcademico gestor, String ruta)
            throws IOException {
        try (PrintWriter pw = new PrintWriter(new BufferedWriter(
                new FileWriter(ruta)))) {

            String fecha = LocalDateTime.now()
                .format(DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm"));

            pw.println("=".repeat(60));
            pw.println("         INFORME ACADEMICO - SISTEMA DE GESTION DE NOTAS");
            pw.println("         Fecha: " + fecha);
            pw.println("=".repeat(60));
            pw.println();

            // Resumen general
            pw.println("--- RESUMEN GENERAL ---");
            pw.printf("Total alumnos: %d%n", gestor.getAlumnos().size());
            pw.printf("Total cursos: %d%n", gestor.getCursos().size());
            pw.printf("Media global: %.2f%n", gestor.getMediaGlobal());
            pw.printf("Aprobados: %d%n", gestor.getAlumnosAprobados().size());
            pw.printf("Suspensos: %d%n", gestor.getAlumnosSuspensos().size());
            pw.println();

            // Listado de alumnos
            pw.println("--- LISTADO DE ALUMNOS ---");
            pw.printf("%-20s %-25s %8s %10s %10s%n",
                "Alumno", "Email", "Notas", "Media", "Estado");
            pw.printf("%-20s %-25s %8s %10s %10s%n",
                "-".repeat(20), "-".repeat(25), "-".repeat(8),
                "-".repeat(10), "-".repeat(10));

            for (Alumno a : gestor.getAlumnos()) {
                pw.printf("%-20s %-25s %8d %10.2f %10s%n",
                    a.getNombre(), a.getEmail(), a.getNumNotas(),
                    a.getNotaMedia(),
                    a.estaAprobado() ? "Aprobado" : "Suspensa");
            }
            pw.println();

            // Estadisticas por curso
            pw.println("--- ESTADISTICAS POR CURSO ---");
            for (Curso c : gestor.getCursos()) {
                pw.printf("%s: %d alumnos, media %.2f%n",
                    c.getNombre(), c.getNumAlumnos(), c.getNotaMediaCurso());
            }
            pw.println();

            // Ranking
            pw.println("--- RANKING DE ALUMNOS ---");
            java.util.List<Alumno> ranking = gestor.getAlumnos();
            ranking.sort(java.util.Comparator.naturalOrder());
            int pos = 1;
            for (Alumno a : ranking) {
                pw.printf("%d. %s (%.2f)%n", pos++, a.getNombre(), a.getNotaMedia());
            }

            pw.println();
            pw.println("=".repeat(60));
            pw.println("         Fin del informe");
            pw.println("=".repeat(60));
        }
    }
}

